'use client'

import * as React from 'react'
import { alertDescriptionVariants, alertTitleVariants, alertVariants, cn } from "@/lib/utils"
import type { VariantProps } from 'class-variance-authority'

const Alert = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement> & VariantProps<typeof alertVariants>
>(({ className, variant, ...props }, ref) => (
  <div
    ref={ref}
    role="alert"
    data-slot="alert"
    className={cn(alertVariants({ variant }), className)}
    {...props}
  />
))
Alert.displayName = 'Alert'

const AlertTitle = React.forwardRef<HTMLHeadingElement, React.HTMLAttributes<HTMLHeadingElement>>(
  ({ className, ...props }, ref) => (
    <h5
      ref={ref}
      data-slot="alert-title"
      className={cn(alertTitleVariants(), className)}
      {...props}
    />
  )
)
AlertTitle.displayName = 'AlertTitle'

const AlertDescription = React.forwardRef<
  HTMLParagraphElement,
  React.HTMLAttributes<HTMLParagraphElement>
>(({ className, ...props }, ref) => (
  <div
    ref={ref}
    data-slot="alert-description"
    className={cn(alertDescriptionVariants(), className)}
    {...props}
  />
))
AlertDescription.displayName = 'AlertDescription'

export { Alert, AlertTitle, AlertDescription }

import { alertVariants } from '../utils'

Component({
  options: {
    styleIsolation: "apply-shared",
  },
  externalClasses: ['ext-class'],
  properties: {
    variant: {
      type: String,
      value: 'default',
    },
    extClass: {
      type: String,
      value: '',
    },
  },
  data: {
    className: '',
  },
  observers: {
    'variant, extClass': function (variant, extClass) {
      this.setData({
        className: alertVariants({ variant, className: extClass }),
      })
    },
  },
})

import { alertDescriptionVariants } from '../utils'

Component({
  options: {
    styleIsolation: "apply-shared",
  },
  externalClasses: ['ext-class'],
  properties: {
    extClass: {
      type: String,
      value: '',
    },
  },
  data: {
    className: '',
  },
  observers: {
    extClass: function (extClass) {
      this.setData({
        className: alertDescriptionVariants({ className: extClass }),
      })
    },
  },
})

.alert-dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.45);
  z-index: 1000;
}

.alert-dialog-content {
  position: fixed;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 80%;
  max-width: 640rpx;
  background: #fff;
  border-radius: 16rpx;
  box-shadow: 0 16rpx 48rpx rgba(0, 0, 0, 0.18);
  z-index: 1001;
  overflow: hidden;
}

.alert-dialog-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 28rpx 28rpx 12rpx;
}

.alert-dialog-title {
  font-size: 32rpx;
  font-weight: 600;
  color: #111827;
}

.alert-dialog-close {
  font-size: 36rpx;
  line-height: 1;
  color: #6b7280;
}

.alert-dialog-body {
  padding: 0 28rpx 20rpx;
  font-size: 28rpx;
  line-height: 1.6;
  color: #374151;
}

.alert-dialog-footer {
  padding: 0 28rpx 28rpx;
}

.alert-dialog-actions {
  display: flex;
  gap: 16rpx;
}

.alert-dialog-cancel-btn,
.alert-dialog-confirm-btn {
  flex: 1;
  text-align: center;
  border-radius: 12rpx;
  padding: 18rpx 0;
  font-size: 28rpx;
}

.alert-dialog-cancel-btn {
  background: #f3f4f6;
  color: #374151;
}

.alert-dialog-confirm-btn {
  background: #111827;
  color: #ffffff;
}

import { resolveClasses } from '../utils'
import {
  dialogContentVariants,
  dialogOverlayVariants,
  dialogCloseVariants,
  dialogTitleVariants,
  dialogDescriptionVariants,
  dialogFooterVariants,
  dialogHeaderVariants,
  buttonVariants,
  alertDialogCancelVariants,
} from "@/lib/utils"
import { setupAlertDialogMachine } from './use-alert-dialog'

type AlertDialogApi = {
  open?: boolean
  backdropProps?: { onClick?: () => void }
  closeTriggerProps?: { onClick?: () => void }
  contentProps?: Record<string, string>
  titleProps?: Record<string, string>
  descriptionProps?: Record<string, string>
}

type MachineEvent = string | { type: string; [key: string]: object }
type MachineSend = (event: MachineEvent) => void

type AlertDialogInstance = WechatMiniprogram.Component.InstanceMethods<AlertDialogApi> & {
  _service?: object
  _cleanup?: () => void
  _send?: MachineSend
  _connect?: (state: object, send: MachineSend) => AlertDialogApi
  data: {
    api: AlertDialogApi
  }
  properties: {
    open: boolean
  }
}

Component({
  options: {
    styleIsolation: 'apply-shared',
    pureDataPattern: /^_/,
  },

  properties: {
    open: { type: Boolean, value: false },
    showTrigger: { type: Boolean, value: true },
    showClose: { type: Boolean, value: true },
    className: { type: String, value: '' },
    title: { type: String, value: '' },
    description: { type: String, value: '' },
    cancelText: { type: String, value: '' },
    confirmText: { type: String, value: '' },
  },

  data: {
    api: {} as AlertDialogApi,
    overlayClass: '',
    contentClass: '',
    titleClass: '',
    descriptionClass: '',
    footerClass: '',
    headerClass: '',
    cancelClass: '',
    confirmClass: '',
    closeClass: '',
  },

  lifetimes: {
    attached() {
      const self = this as AlertDialogInstance
      const { controller, connect } = setupAlertDialogMachine(this)

      self._service = controller.service
      self._cleanup = controller.start()
      self._send = controller.send as MachineSend
      self._connect = connect
    },
    detached() {
      const self = this as AlertDialogInstance
      self._cleanup?.()
    },
  },

  observers: {
    'state': function (state) {
      const self = this as AlertDialogInstance
      if (!state || !self._send || !self._connect) return

      const api = self._connect(state, self._send) as AlertDialogApi

      const overlayClass = resolveClasses(dialogOverlayVariants())
      const contentClass = resolveClasses(dialogContentVariants(), this.properties.className)
      const titleClass = resolveClasses(dialogTitleVariants())
      const descriptionClass = resolveClasses(dialogDescriptionVariants())
      const footerClass = resolveClasses(dialogFooterVariants())
      const headerClass = resolveClasses(dialogHeaderVariants())
      const cancelClass = resolveClasses(alertDialogCancelVariants())
      const confirmClass = resolveClasses(buttonVariants())
      const closeClass = resolveClasses(dialogCloseVariants())

      this.setData({
        api,
        overlayClass,
        contentClass,
        titleClass,
        descriptionClass,
        footerClass,
        headerClass,
        cancelClass,
        confirmClass,
        closeClass
      })
    },

    'open': function (val) {
      const self = this as AlertDialogInstance
      if (self._service) {
        if (val !== self.data.api.open) {
          self._send?.(val ? 'OPEN' : 'CLOSE')
        }
      }
    },
  },

  methods: {
    onTriggerTap() {
      const self = this as AlertDialogInstance
      self._send?.('OPEN')
    },
    onBackdropTap() {
      const self = this as AlertDialogInstance
      self.data.api.backdropProps?.onClick?.()
    },
    onCloseTap() {
      const self = this as AlertDialogInstance
      self.data.api.closeTriggerProps?.onClick?.()
    },
    onCancelTap() {
      this.triggerEvent('cancel')
      const self = this as AlertDialogInstance
      self._send?.('CLOSE')
    },
    onConfirmTap() {
      this.triggerEvent('confirm')
      const self = this as AlertDialogInstance
      self._send?.('CLOSE')
    },
    noop() { }
  },
})

import { alertTitleVariants } from '../utils'

Component({
  options: {
    styleIsolation: "apply-shared",
  },
  externalClasses: ['ext-class'],
  properties: {
    extClass: {
      type: String,
      value: '',
    },
  },
  data: {
    className: '',
  },
  observers: {
    extClass: function (extClass) {
      this.setData({
        className: alertTitleVariants({ className: extClass }),
      })
    },
  },
})
